const hex = (s: string) => new Uint8Array(Buffer.from(s, "hex"));
const toHex = (b: Uint8Array) => Buffer.from(b).toString("hex");

test("Noise_NK_25519_ChaChaPoly_SHA256 matches official specification test vectors byte-for-byte", () => {
  for (const vec of NK_VECTORS) {
    const respKp = x25519KeypairFromPrivate(hex(vec.respStatic));
    assert.equal(toHex(respKp.publicKey), vec.respStaticPub);

    const prologue = hex(vec.prologue);
    const m0 = vec.messages[0]!;
    const m1 = vec.messages[1]!;

    const { message1, state } = startNkInitiator({
      responderStaticPublicKey: respKp.publicKey,
      prologue,
      payload: hex(m0.payload),
      ephemeralPrivateKey: hex(vec.initEphemeral),
    });
    assert.equal(toHex(message1), m0.ciphertext);

    const resp = respondNk({
      responderStaticKeypair: respKp,
      message1,
      prologue,
      responsePayload: hex(m1.payload),
      ephemeralPrivateKey: hex(vec.respEphemeral),
    });
    assert.equal(toHex(resp.clientPayload), m0.payload);
    assert.equal(toHex(resp.message2), m1.ciphertext);

    const initDone = state.completeMessage2(resp.message2);
    assert.equal(toHex(initDone.payload), m1.payload);
    assert.equal(toHex(initDone.session.handshakeHash), toHex(resp.session.handshakeHash));

    assertTransportVectors(initDone.session, resp.session, vec.messages);
    initDone.session.destroy();
    resp.session.destroy();
  }
});

/** Transport messages 2..n alternate initiator → responder (even) and responder → initiator (odd). */
function assertTransportVectors(
  initiator: NoiseSession,
  responder: NoiseSession,
  messages: readonly { payload: string; ciphertext: string }[],
): void {
  for (let i = 2; i < messages.length; i++) {
    const msg = messages[i]!;
    const [from, to] = i % 2 === 0 ? [initiator, responder] : [responder, initiator];
    const ct = from.send.encryptWithAd(new Uint8Array(0), hex(msg.payload));
    assert.equal(toHex(ct), msg.ciphertext, `transport message ${i}`);
    assert.equal(toHex(to.receive.decryptWithAd(new Uint8Array(0), ct)), msg.payload, `transport message ${i}`);
  }
}

test("Noise_IK_25519_ChaChaPoly_SHA256 matches official specification test vectors byte-for-byte", () => {
  for (const vec of IK_VECTORS) {
    const initKp = x25519KeypairFromPrivate(hex(vec.initStatic));
    const respKp = x25519KeypairFromPrivate(hex(vec.respStatic));
    assert.equal(toHex(respKp.publicKey), vec.initRemoteStatic);

    const prologue = hex(vec.prologue);
    const m0 = vec.messages[0]!;
    const m1 = vec.messages[1]!;

    // -> e, es, s, ss
    const { message1, state } = startIkInitiator({
      initiatorStaticKeypair: initKp,
      responderStaticPublicKey: hex(vec.initRemoteStatic),
      prologue,
      payload: hex(m0.payload),
      ephemeralPrivateKey: hex(vec.initEphemeral),
    });
    assert.equal(toHex(message1), m0.ciphertext);

    // <- e, ee, se
    const resp = respondIk({
      responderStaticKeypair: respKp,
      message1,
      prologue,
      responsePayload: hex(m1.payload),
      ephemeralPrivateKey: hex(vec.respEphemeral),
    });
    assert.equal(toHex(resp.initiatorStaticPublicKey), toHex(initKp.publicKey));
    assert.equal(toHex(resp.clientPayload), m0.payload);
    assert.equal(toHex(resp.message2), m1.ciphertext);

    const initDone = state.completeMessage2(resp.message2);
    assert.equal(toHex(initDone.payload), m1.payload);
    assert.equal(toHex(initDone.session.handshakeHash), toHex(resp.session.handshakeHash));

    assertTransportVectors(initDone.session, resp.session, vec.messages);
    initDone.session.destroy();
    resp.session.destroy();
  }
});

test("Noise_IK_25519_ChaChaPoly_SHA256 hides client static key on the wire, authenticates mutually, and rejects revoked keys", () => {
  const hostKp = x25519KeypairFromPrivate(
    hex("1111111111111111111111111111111111111111111111111111111111111111"),
  );
  const phoneKp = x25519KeypairFromPrivate(
    hex("2222222222222222222222222222222222222222222222222222222222222222"),
  );

  const { message1, state } = startIkInitiator({
    initiatorStaticKeypair: phoneKp,
    responderStaticPublicKey: hostKp.publicKey,
    prologue: LUMENBOX_RELAY_PROLOGUE,
    payload: Buffer.from("hello-mac", "utf8"),
  });

  // Phone's static public key must be encrypted inside message1, never visible in cleartext!
  assert.equal(Buffer.from(message1).includes(Buffer.from(phoneKp.publicKey)), false);

  const resp = respondIk({
    responderStaticKeypair: hostKp,
    message1,
    prologue: LUMENBOX_RELAY_PROLOGUE,
    admitInitiator: (clientPub, payload) => {
      assert.equal(toHex(clientPub), toHex(phoneKp.publicKey));
      assert.equal(Buffer.from(payload).toString("utf8"), "hello-mac");
      return Buffer.from("admitted-ok", "utf8");
    },
  });

  const init = state.completeMessage2(resp.message2);
  assert.equal(Buffer.from(init.payload).toString("utf8"), "admitted-ok");
  assert.equal(toHex(init.session.handshakeHash), toHex(resp.session.handshakeHash));

  // Revoked / unknown device rejection inside admitInitiator
  assert.throws(
    () =>
      respondIk({
        responderStaticKeypair: hostKp,
        message1,
        prologue: LUMENBOX_RELAY_PROLOGUE,
        admitInitiator: () => {
          throw new NoiseError("device_revoked", "Device revoked");
        },
      }),
    (err: unknown) => err instanceof NoiseError && err.code === "device_revoked",
  );

  init.session.destroy();
  resp.session.destroy();
});

const isNoiseError = (code: string) => (err: unknown) => err instanceof NoiseError && err.code === code;

test("Noise_IK fails the handshake when either side holds the wrong responder static key", () => {
  const hostKp = generateX25519Keypair();
  const phoneKp = generateX25519Keypair();
  const otherKp = generateX25519Keypair();

  // The phone addresses a key that is not the host's: the host cannot open the encrypted `s`
  // (its `es` differs), so it learns neither the phone's identity nor its payload.
  const misaddressed = startIkInitiator({
    initiatorStaticKeypair: phoneKp,
    responderStaticPublicKey: otherKp.publicKey,
    payload: Buffer.from("hello"),
  });
  assert.throws(
    () => respondIk({ responderStaticKeypair: hostKp, message1: misaddressed.message1 }),
    isNoiseError("decrypt_failed"),
  );

  // Something without the host's private key answers a message meant for the host (a relay
  // impersonating the Mac): it cannot open message 1, so it can never produce a message 2.
  const { message1 } = startIkInitiator({
    initiatorStaticKeypair: phoneKp,
    responderStaticPublicKey: hostKp.publicKey,
  });
  assert.throws(
    () => respondIk({ responderStaticKeypair: otherKp, message1 }),
    isNoiseError("decrypt_failed"),
  );
});

test("Noise_IK: a decryption failure ends the handshake, and a destroyed cipher state refuses to be used", () => {
  const hostKp = generateX25519Keypair();
  const phoneKp = generateX25519Keypair();
  const flipLast = (b: Uint8Array) => {
    const out = new Uint8Array(b);
    out[out.byteLength - 1]! ^= 0x01;
    return out;
  };

  // Responder: a tampered message 1 is refused; respondIk keeps no state between calls.
  const first = startIkInitiator({ initiatorStaticKeypair: phoneKp, responderStaticPublicKey: hostKp.publicKey });
  assert.throws(
    () => respondIk({ responderStaticKeypair: hostKp, message1: flipLast(first.message1) }),
    isNoiseError("decrypt_failed"),
  );

  // Initiator: once message 2 has failed to decrypt, the handshake state is spent (Noise §5:
  // "the handshake has failed and the HandshakeState is deleted") — the genuine message 2 that
  // arrives afterwards no longer completes it.
  const resp = respondIk({ responderStaticKeypair: hostKp, message1: first.message1 });
  assert.throws(() => first.state.completeMessage2(flipLast(resp.message2)), isNoiseError("decrypt_failed"));
  assert.throws(() => first.state.completeMessage2(resp.message2), isNoiseError("decrypt_failed"));

  // Transport: Noise §5.1 says a failed DecryptWithAd does not increment n and only discards the
  // message (the AEAD record test below shows the next genuine record still opens). Our
  // application takes the spec's other option: RelayMux closes and destroys the session on any
  // record error. A destroyed CipherState must then refuse, not fall back to the empty-key
  // pass-through that would send plaintext.
  const second = startIkInitiator({ initiatorStaticKeypair: phoneKp, responderStaticPublicKey: hostKp.publicKey });
  const host = respondIk({ responderStaticKeypair: hostKp, message1: second.message1 });
  const phone = second.state.completeMessage2(host.message2);
  const ct = phone.session.send.encryptWithAd(new Uint8Array(0), Buffer.from("secret"));
  assert.throws(() => host.session.receive.decryptWithAd(new Uint8Array(0), flipLast(ct)), isNoiseError("decrypt_failed"));
  host.session.destroy();
  phone.session.destroy();
  assert.throws(
    () => phone.session.send.encryptWithAd(new Uint8Array(0), Buffer.from("secret")),
    isNoiseError("cipher_destroyed"),
  );
  assert.throws(() => host.session.receive.decryptWithAd(new Uint8Array(0), ct), isNoiseError("cipher_destroyed"));
});

test("CipherState refuses to encrypt or decrypt once the nonce reaches the reserved 2^64-1", () => {
  const key = new Uint8Array(32).fill(0x07);
  const sender = new CipherState(key);
  const receiver = new CipherState(key);
  // Noise has SetNonce(); this implementation does not export one, so the test reaches the
  // private counter directly rather than add a production way to rewind a nonce.
  const lastUsable = (1n << 64n) - 2n;
  (sender as unknown as { nonce: bigint }).nonce = lastUsable;
  (receiver as unknown as { nonce: bigint }).nonce = lastUsable;

  const ct = sender.encryptWithAd(new Uint8Array(0), Buffer.from("last"));
  assert.equal(Buffer.from(receiver.decryptWithAd(new Uint8Array(0), ct)).toString("utf8"), "last");
  assert.equal(sender.currentNonce(), lastUsable + 1n);
  assert.equal(receiver.currentNonce(), lastUsable + 1n);

  assert.throws(() => sender.encryptWithAd(new Uint8Array(0), Buffer.from("one more")), isNoiseError("nonce_exhausted"));
  assert.throws(() => receiver.decryptWithAd(new Uint8Array(0), ct), isNoiseError("nonce_exhausted"));
  // Refusing does not consume or wrap the counter.
  assert.equal(sender.currentNonce(), lastUsable + 1n);
});

test("isCanonicalX25519PublicKey rejects low-order torsion points and coordinates >= 2^255 - 19", () => {
  const valid = generateX25519Keypair().publicKey;
  assert.equal(isCanonicalX25519PublicKey(valid), true);

  // Low-order points
  assert.equal(isCanonicalX25519PublicKey(new Uint8Array(32)), false);
  const one = new Uint8Array(32);
  one[0] = 1;
  assert.equal(isCanonicalX25519PublicKey(one), false);
  assert.equal(
    isCanonicalX25519PublicKey(
      hex("e0eb7a7c3b41b8ae1656e3faf19fc46ada098deb9c32b1fd866205165f49b800"),
    ),
    false,
  );
  assert.equal(
    isCanonicalX25519PublicKey(
      hex("ecffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff7f"),
    ),
    false,
  );

  // Non-canonical (>= p = 2^255 - 19)
  assert.equal(
    isCanonicalX25519PublicKey(
      hex("edffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff7f"),
    ),
    false,
  );
  assert.equal(isCanonicalX25519PublicKey(new Uint8Array(32).fill(0xff)), false);
});

test("AEAD record framing handles multi-chunk payloads and rejects replay, reordering, tampering, and 4 GiB forged headers without allocating", () => {
  const key = new Uint8Array(32).fill(0x42);
  const sender = new CipherState(key);
  const receiver = new CipherState(key);

  // Multi-chunk round trip (> 2 * MAX_CHUNK_DATA_BYTES)
  const big = new Uint8Array(MAX_CHUNK_DATA_BYTES * 2 + 1234);
  for (let i = 0; i < big.byteLength; i++) big[i] = i & 0xff;

  const wire = sealRecord(sender, { kind: RECORD_KIND_BINARY, streamId: 7, payload: big });
  const opened = openRecord(receiver, wire);
  assert.equal(opened.kind, RECORD_KIND_BINARY);
  assert.equal(opened.streamId, 7);
  assert.deepEqual(opened.payload, big);

  // Replay of the exact same wire record fails because receiver counter advanced!
  assert.throws(
    () => openRecord(receiver, wire),
    (err: unknown) => err instanceof RecordFrameError && err.code === "decrypt_failed",
  );

  // Out-of-order delivery fails
  const wireA = sealRecord(sender, {
    kind: RECORD_KIND_TEXT,
    streamId: 1,
    payload: Buffer.from("A"),
  });
  const wireB = sealRecord(sender, {
    kind: RECORD_KIND_TEXT,
    streamId: 1,
    payload: Buffer.from("B"),
  });
  assert.throws(
    () => openRecord(receiver, wireB),
    (err: unknown) => err instanceof RecordFrameError && err.code === "decrypt_failed",
  );
  // Receiver counter did NOT advance on failed authentication, so wireA still opens cleanly!
  const openedA = openRecord(receiver, wireA);
  assert.equal(Buffer.from(openedA.payload).toString("utf8"), "A");
  const openedB = openRecord(receiver, wireB);
  assert.equal(Buffer.from(openedB.payload).toString("utf8"), "B");

  // Forged plaintext header claiming 4 GiB (0xffff_ffff) inside a valid AEAD ciphertext is
  // rejected BEFORE allocating any 4 GiB buffer!
  const badPlain = Buffer.alloc(15, 0);
  badPlain[0] = RECORD_KIND_BINARY;
  badPlain[1] = CHUNK_FLAG_FIRST | CHUNK_FLAG_FINAL;
  badPlain.writeUInt32BE(0xffff_ffff, 2); // 4 GiB claim!
  badPlain.writeUInt32BE(9, 6);
  const forgedCt = sender.encryptWithAd(new Uint8Array(0), badPlain);
  const forgedWire = Buffer.allocUnsafe(2 + forgedCt.byteLength);
  forgedWire.writeUInt16BE(forgedCt.byteLength, 0);
  forgedWire.set(forgedCt, 2);

  const rssBefore = process.memoryUsage().heapUsed;
  assert.throws(
    () => openRecord(receiver, forgedWire),
    (err: unknown) => err instanceof RecordFrameError && err.code === "length_mismatch",
  );
  const rssDelta = process.memoryUsage().heapUsed - rssBefore;
  assert.ok(rssDelta < 5 * 1024 * 1024, `expected zero large allocation, heap delta=${rssDelta}`);

  // Reserved flags rejected
  const rsvPlain = Buffer.alloc(10, 0);
  rsvPlain[0] = RECORD_KIND_TEXT;
  rsvPlain[1] = CHUNK_FLAG_FIRST | CHUNK_FLAG_FINAL | 0x80;
  const rsvCt = sender.encryptWithAd(new Uint8Array(0), rsvPlain);
  const rsvWire = Buffer.allocUnsafe(2 + rsvCt.byteLength);
  rsvWire.writeUInt16BE(rsvCt.byteLength, 0);
  rsvWire.set(rsvCt, 2);
  assert.throws(
    () => openRecord(receiver, rsvWire),
    (err: unknown) => err instanceof RecordFrameError && err.code === "reserved_flags",
  );
});
